p='src/server/repositories/comment-repository.ts'
s=open(p).read()
start=s.index("/**\n * The whole thread for one issue")
end=s.index("export async function countComments")
new='''/**
 * The whole thread for one issue, in reading order: top-level comments oldest
 * first, each followed by every reply that descends from it — directly or
 * through other replies — in order of posting. A deleted comment keeps its
 * place as a placeholder (still carrying `archivedAt`, but no text) so the
 * replies beneath it stay anchored where they were.
 */
export async function listThread(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly CommentThreadNode[]> {
  const rows = getDb()
    .select({ comment: comments, author: users })
    .from(comments)
    .innerJoin(users, eq(users.id, comments.authorId))
    .where(
      and(
        orgPredicate(comments.orgId, orgId),
        eq(comments.issueId, issueId),
      ),
    )
    // `rowid` breaks ties between comments stamped in the same millisecond.
    .orderBy(asc(comments.createdAt), sql`"comments".rowid`)
    .all();

  const decorated: CommentWithAuthor[] = rows.map((row) => ({
    ...toComment(row.comment),
    author: toUser(row.author),
  }));

  const position = new Map<string, number>();
  const repliesTo = new Map<string, CommentWithAuthor[]>();
  decorated.forEach((comment, index) => {
    position.set(comment.id, index);
    if (comment.parentId === null) return;
    const bucket = repliesTo.get(comment.parentId) ?? [];
    bucket.push(comment);
    repliesTo.set(comment.parentId, bucket);
  });

  return decorated
    .filter((comment) => comment.parentId === null)
    .map((root) => {
      const descendants: CommentWithAuthor[] = [];
      const visited = new Set<string>([root.id]);
      const pending = [root.id];

      for (let id = pending.pop(); id !== undefined; id = pending.pop()) {
        for (const reply of repliesTo.get(id) ?? []) {
          if (visited.has(reply.id)) continue;
          visited.add(reply.id);
          descendants.push(reply);
          pending.push(reply.id);
        }
      }

      descendants.sort(
        (a, b) => (position.get(a.id) ?? 0) - (position.get(b.id) ?? 0),
      );

      return {
        comment: asPlaceholderIfDeleted(root),
        replies: descendants.map(asPlaceholderIfDeleted),
      };
    });
}

/** A deleted comment stays in the thread but never exposes its text. */
function asPlaceholderIfDeleted(comment: CommentWithAuthor): CommentWithAuthor {
  return comment.archivedAt === null
    ? comment
    : { ...comment, body: "", mentionedUserIds: [] };
}

'''
s=s[:start]+new+s[end:]
s=s.replace('import { and, asc, count, desc, eq, isNull } from "drizzle-orm";','import { and, asc, count, desc, eq, isNull, sql } from "drizzle-orm";')

old=s[s.index("/** An edit stamps `edited_at`"):s.index("export async function archiveComment")]
new2='''/**
 * An edit stamps `edited_at`, which the UI shows next to the timestamp. When
 * `mentionedUserIds` is given it replaces the recorded mentions, so the row
 * always agrees with the text it holds.
 */
export async function updateComment(
  input: UpdateCommentInput,
  mentionedUserIds?: readonly UserId[],
): Promise<Comment> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .update(comments)
    .set({
      body: input.body,
      editedAt: stamp,
      updatedAt: stamp,
      ...(mentionedUserIds === undefined
        ? {}
        : { mentionedUserIds: JSON.stringify(mentionedUserIds) }),
    })
    .where(
      and(
        orgPredicate(comments.orgId, input.orgId),
        eq(comments.id, input.commentId),
      ),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Comment ${input.commentId} not found`);
  return toComment(row);
}

'''
s=s.replace(old,new2)
open(p,'w').write(s)
EOF
