/**
 * End-to-end comment behaviour: mentions, alerts, threads, edits, rate limit.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { resetRateLimits } from "@/lib/rate-limit";
import * as memberRepo from "@/server/repositories/member-repository";
import * as userRepo from "@/server/repositories/user-repository";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import { listNotifications } from "@/server/services/notification-service";
import * as searchService from "@/server/services/search-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { CommentId, UserId } from "@/types/common";
import type { Issue } from "@/types/issue";
import type { Actor } from "@/types/member";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;
let detach: Unsubscribe;
let tenant: Tenant;
let issue: Issue;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detach = searchService.registerSearchListeners();
  tenant = await createTenant("flow", "growth");
  issue = await issueService.createIssue(
    tenant.actors.member,
    issueInput(tenant.org.id, tenant.project.id, {
      title: "Flow target",
      assigneeId: tenant.userIds.admin,
    }),
  );
});

afterAll(() => {
  detach();
  cleanup();
});

afterEach(() => {
  vi.useRealTimers();
  resetRateLimits();
});

function post(actor: Actor, body: string, parentId: CommentId | null = null) {
  return commentService.createComment(actor, {
    orgId: tenant.org.id,
    issueId: issue.id,
    body,
    parentId,
    mentionedUserIds: [],
  });
}

async function alertsFor(userId: UserId) {
  const page = await listNotifications(tenant.actors.owner, {
    orgId: tenant.org.id,
    recipientId: userId,
    unreadOnly: false,
    limit: 100,
    cursor: null,
  });
  return page.items;
}

describe("comment flow", () => {
  it("mentions the longest-standing members of a big workspace, viewers included", async () => {
    const early = await userRepo.insertUser({
      email: "Early.Bird@flow.test",
      name: "Early",
      passwordHash: "x",
    });
    await memberRepo.insertMember(tenant.org.id, early.id, "viewer", null);
    for (let i = 0; i < 130; i += 1) {
      const user = await userRepo.insertUser({
        email: `filler${i}@flow.test`,
        name: `Filler ${i}`,
        passwordHash: "x",
      });
      await memberRepo.insertMember(tenant.org.id, user.id, "member", null);
    }

    const comment = await post(tenant.actors.member, "ping @early.bird and @member");
    expect(comment.mentionedUserIds).toEqual([early.id]);
  });

  it("alerts each person once, mention over comment, reply author included", async () => {
    const top = await post(tenant.actors.owner, "top-level by owner");
    const reply = await post(
      tenant.actors.viewer === undefined ? tenant.actors.member : tenant.actors.admin,
      "reply, cc @admin and @owner",
      top.id,
    );
    void reply;

    const adminAlerts = (await alertsFor(tenant.userIds.admin)).filter((n) =>
      n.body.includes(issue.id),
    );
    const ownerAlerts = await alertsFor(tenant.userIds.owner);
    expect(ownerAlerts.filter((n) => n.kind === "comment_mention")).toHaveLength(1);
    // admin authored the reply: nothing for them from it
    expect(adminAlerts.filter((n) => n.kind === "comment_mention")).toHaveLength(0);
  });

  it("does not double-alert an assignee who is also mentioned", async () => {
    const before = (await alertsFor(tenant.userIds.admin)).length;
    await post(tenant.actors.member, "hey @admin");
    const after = await alertsFor(tenant.userIds.admin);
    expect(after.length - before).toBe(1);
    expect(after[0]?.kind).toBe("comment_mention");
  });

  it("lists replies to replies and keeps deleted comments as placeholders", async () => {
    const top = await post(tenant.actors.member, "thread root");
    const r1 = await post(tenant.actors.admin, "first reply", top.id);
    const r2 = await post(tenant.actors.member, "reply to reply", r1.id);
    const r3 = await post(tenant.actors.admin, "deeper", r2.id);
    const r4 = await post(tenant.actors.member, "second direct", top.id);

    await commentService.deleteComment(tenant.actors.admin, {
      orgId: tenant.org.id,
      commentId: r1.id,
    });
    await commentService.deleteComment(tenant.actors.admin, {
      orgId: tenant.org.id,
      commentId: top.id,
    });

    const thread = await commentService.getThread(tenant.actors.member, tenant.org.id, issue.id);
    const node = thread.find((n) => n.comment.id === top.id);
    expect(node?.comment.archivedAt).not.toBeNull();
    expect(node?.comment.body).toBe("");
    expect(node?.replies.map((r) => r.id)).toEqual([r1.id, r2.id, r3.id, r4.id]);
    expect(node?.replies[0]?.body).toBe("");
    expect(node?.replies[1]?.body).toBe("reply to reply");
  });

  it("edits: window from posting, mentions re-read, alerts once, search updated", async () => {
    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(new Date("2026-02-01T00:00:00.000Z"));
    const comment = await post(tenant.actors.member, "plain words @owner");

    vi.setSystemTime(new Date("2026-02-01T00:10:00.000Z"));
    const ownerBefore = (await alertsFor(tenant.userIds.owner)).length;
    const adminBefore = (await alertsFor(tenant.userIds.admin)).length;
    const edited = await commentService.updateComment(tenant.actors.member, {
      orgId: tenant.org.id,
      commentId: comment.id,
      body: "zebrafish @owner @admin",
    });
    expect(edited.mentionedUserIds).toEqual([tenant.userIds.owner, tenant.userIds.admin]);
    expect((await alertsFor(tenant.userIds.owner)).length).toBe(ownerBefore);
    expect((await alertsFor(tenant.userIds.admin)).length).toBe(adminBefore + 1);

    const hits = await searchService.search(tenant.actors.member, {
      orgId: tenant.org.id,
      q: "zebrafish",
      kinds: ["comment"],
      limit: 25,
      cursor: null,
    });
    expect(hits.items.map((h) => h.id)).toEqual([comment.id]);

    vi.setSystemTime(new Date("2026-02-01T00:16:00.000Z"));
    await expect(
      commentService.updateComment(tenant.actors.member, {
        orgId: tenant.org.id,
        commentId: comment.id,
        body: "too late",
      }),
    ).rejects.toThrow(/edit window/);
    await expect(
      commentService.updateComment(tenant.actors.admin, {
        orgId: tenant.org.id,
        commentId: comment.id,
        body: "admin may",
      }),
    ).resolves.toMatchObject({ body: "admin may" });
  });

  it("rate-limits per member", async () => {
    let failed = false;
    for (let i = 0; i < 2000 && !failed; i += 1) {
      try {
        await post(tenant.actors.member, `burst ${i}`);
      } catch (error) {
        failed = /rate limit/i.test(String(error));
        if (!failed) throw error;
      }
    }
    expect(failed).toBe(true);
    await expect(post(tenant.actors.admin, "still fine")).resolves.toBeDefined();
  });
});
EOF
